import sys,time

def sprint(str):
   for c in str + '\n':
     sys.stdout.write(c)
     sys.stdout.flush()
     time.sleep(3./90)

def main():
  sprint("You were reincarnated into the Wei Family")
  sprint("===========================================")
  sprint("Instructions: Type A) or B) etc. whenever prompted\n")
  game()

