 Answer = (input("White, A), Black, B),  Red, C)"))
 if Answer == ("A)"): 
  sprint("you take the Family heirloom and head to the Capital, where the great sect exam is taking place.")
  player_blaade1()
 if Answer == ("B)"):
  sprint("you take your great grandfather's blade and head to the Capital, where the great sect exam is taking place.")
  player_blaade1()
 
 else: 
    sprint("you sense something unsettling about the blade, but take it anyway and head to the capital, where the great sect exam is taking place")
    player_demon1()


